    for (let dy = -s; dy <= s; dy++) {
      if (Math.abs(dy) === s) {
        for (let dx = -s; dx <= s; dx++) {
          outlines.push([CENTER.x + dx, CENTER.y + 0, CENTER.z + dy]);
        }
      }
