async function construirPiramideDeAreia() {
  const pos = world.getPosition(bot);
  // Ponto central horizontal; base começa 1 bloco acima do bot.
  const center = { x: pos.x, y: pos.y + 1, z: pos.z };

  // Tamanho desejado (largura/profundidade da base). Use número ímpar para centrar bem.
  const LADO_BASE = 128;
  const HALF = Math.floor(LADO_BASE / 2);
  const MATERIAL = 'sandstone';

  const layers = [];

  for (let i = 0; i <= HALF; i++) {
    const s = Math.max(0, HALF - i); // raio da camada atual (decai até 0 no topo)
    const x0 = center.x - s;
    const z0 = center.z - s;

    // Apenas a casca externa (bordas) para não deixar o miolo cheio
    const blocosDaCamada = [];
    for (let dz = -s; dz <= s; dz++) {
      if (Math.abs(dz) === s) {
        for (let dx = -s; dx <= s; dx++) {
          blocosDaCamada.push([center.x + dx, center.y + 0, center.z + dz]);
        }
      }
    }
    // Camada do topo: única pedra
    if (s === 0) {
      blocosDaCamada.push([center.x, center.y + 0, center.z]);
    }

    // y é fixo para toda a camada (uma "fileira" de blocos)
    const camada = { y: center.y + 0, blocos: blocosDaCamada };
    layers.push(camada);

    // Se quiser espessura de parede > 1, aumente o raio interno:
    // const wallThickness = 1;
    // const innerRadius = s - wallThickness;
    // ...
  }

  // Constrói cada camada usando as bordas
  for (const camada of layers) {
    const promises = camada.blocos.map(([bx, _, bz]) => {
      const x = bx;
      const z = bz;
      const blocoExistente = world.getBlockAt?.(x, camada.y, z)?.type;
      if (blocoExistente && blocoExistente !== 'air') return;

      // Em vez de await individual, paraleliza os blocos da mesma camada
      // (mantenha sequencial se preferir idêntico ao exemplo)
      return skills.placeBlock(bot, MATERIAL, x, camada.y, z);
    });
    await Promise.all(promises);
  }

  console.log('Pirâmide de areia construída.');
}

construirPiramideDeAreia();
```
