/**
 * Constrói uma pirâmide de areia (casca vazada) centrada na posição do bot.
 * Ajuste LADO_BASE, CENTER.y e a inclinação se necessário.
 */
async function construirPiramideDeAreia() {
  const pos = world.getPosition(bot);

  // Centro horizontal usa a posição do bot.
  // A base fica 1 bloco acima do solo (pos.y + 1). Altere se quiser ancorar no chão.
  const center = { x: pos.x, y: pos.y + 1, z: pos.z };

  // Largura/Profundidade da base em blocos (use número ímpar para simetria)
  const LADO_BASE = 127;       // base de 127x127
  const METADE_BASE = Math.floor(LADO_BASE / 2); // 63
  const MATERIAL = 'sandstone';

  const camadas = [];

  // Deixa o raio ir de METADE_BASE até 0 (topo). Cada camada perde 1 de raio.
  // Isso dá uma inclinação de 45° (1 subindo, 2 encolhendo de largura).
  for (let i = 0; i <= METADE_BASE; i++) {
    const y = center.y + i;
    const s = Math.max(0, METADE_BASE - i); // raio da camada atual

    const xMin = center.x - s;
    const zMin = center.z - s;

    // Coloca somente a borda da camada (casca de 1 bloco, miolo oco)
    const blocosDaCamada = [];
    for (let dx = -s; dx <= s; dx++) {
      for (let dz = -s; dz <= s; dz++) {
        // Borda da malha quadrada desta camada
        if (Math.abs(dx) === s || Math.abs(dz) === s) {
          blocosDaCamada.push([center.x + dx, y, center.z + dz]);
        }
      }
    }

    // Camada do topo: bloco único central
    if (s === 0) {
      blocosDaCamada.push([center.x, y, center.z]);
    }

    camadas.push({ blocos: blocosDaCamada, y });
  }

  // Constrói as camadas respeitando blocos já existentes
  for (const { blocos, y } of camadas) {
    for (const [x, z] of blocos) {
      // Ignora blocos que já existem
      const blocoAtual = world.getBlockAt(x, y, z);
      if (blocoAtual && typeof blocoAtual.type === 'string' && blocoAtual.type !== 'air') {
        continue;
      }
      await skills.placeBlock(bot, MATERIAL, x, y, z);
    }
  }

  console.log('Pirâmide de areia construída!');
}

construirPiramideDeAreia();
```

